    "proxy": "Proxy configuration for outbound HTTP/HTTPS/SOCKS5 traffic (`[proxy]`).",
    "query_classification": "Automatic query classification — maps user messages to model hints.",
    "relay": "Nominated-relay client for reaching this daemon through a relay (`[relay]`).",
    "reliability": "Reliability settings: retries, backoff, key rotation (`[reliability]`).",
    "risk_profiles": "Named risk/autonomy profiles (`[risk_profiles.<alias>]`).",
    "runtime": "Runtime adapter configuration (`[runtime]`). Controls native vs Docker execution.",
    "runtime_profiles": "Named runtime/LLM execution profiles (`[runtime_profiles.<alias>]`).",
