    "schema_version": "Config file schema version.",
    "secrets": "Secrets encryption configuration (`[secrets]`).",
    "security": "Security subsystem configuration (`[security]`).",
    "security_ops": "Managed cybersecurity service configuration (`[security_ops]`).",
    "shell_tool": "Shell tool configuration (`[shell_tool]`).",
    "skill_bundles": "Named skill bundles (`[skill_bundles.<alias>]`).",
    "skills": "Skills loading and community repository behavior (`[skills]`).",
    "sop": "Standard Operating Procedures engine configuration (`[sop]`).",
    "storage": "Persistent storage model_provider configuration (`[storage]`).",
    "text_browser": "Text browser tool configuration (`[text_browser]`).",
    "transcription": "Voice transcription configuration (Whisper API via Groq).",
