  "DelegateTargetConfig": {
    "agent": "Target agent alias.",
    "mode": "Whether this target is parent-bounded or independent."
  },
  "DelegateToolConfig": {
    "agentic_timeout_secs": "Default timeout in seconds for agentic sub-agent runs.\nCan be overridden per-agent in `[agents.<name>]` config.\nDefault: 300 seconds.",
    "timeout_secs": "Default timeout in seconds for non-agentic sub-agent model_provider calls.\nCan be overridden per-agent in `[agents.<name>]` config.\nDefault: 120 seconds."
  },
  "DeliveryConfigDecl": {
    "best_effort": "Best-effort delivery. Default: `true`.",
    "channel": "Channel to deliver to, as `<type>.<alias>` (e.g.\n`\"telegram.work\"`, `\"discord.ops\"`). A bare type (`\"telegram\"`)\nresolves only while that type has exactly one configured instance,\nso prefer the aliased form.",
    "mode": "Delivery mode: `\"none\"` or `\"announce\"`.",
    "thread_id": "Optional thread/conversation identifier carried into the outbound send.\nRequired by channels that route on a separate `thread_id` field (e.g.\nwebhook callbacks bridging into agent-chat platforms).",
    "to": "Target/recipient identifier."
  },
  "DingTalkConfig": {
    "client_id": "Client ID (AppKey) from DingTalk developer console",
    "client_secret": "Client Secret (AppSecret) from DingTalk developer console",
    "enabled": "Whether this channel is active. The runtime only loads channels whose\n`enabled = true`. Default: `false` so an operator who pastes a partial\n`[channels.<type>.<alias>]` block doesn't accidentally bring a channel\nlive before the rest of its config is filled in.",
    "excluded_tools": "Tools excluded from this channel's tool spec. When set, these tools\nare not exposed to the model when responding via this channel.",
    "proxy_url": "Per-channel proxy URL (http, https, socks5, socks5h).\nOverrides the global `[proxy]` setting for this channel only."
  },
  "DiscordConfig": {
    "approval_timeout_secs": "Seconds to wait for operator approval on `always_ask` tools before auto-denying.",
    "archive": "When true, the channel opens a sidecar `discord.db` SQLite memory\nbackend, archives every non-bot message it sees, and registers the\n`discord_search` tool against it. Default: false. Folded in from\nthe legacy `[channels.discord-history]` block.",
    "bot_token": "Discord bot token (from Discord Developer Portal). `#[serde(default)]`\nfor the same reason as `TelegramConfig::bot_token`: a missing token\nmust deserialize as an empty string instead of salvage-dropping the\nalias; `validate_bot_token` still requires a real token once\n`enabled = true`.",
    "channel_ids": "Channel IDs to watch. Empty = watch every channel the bot can see.\nUsed by the archive sidecar (when `archive = true`) and by the\nin-channel filter when set.",
    "draft_update_interval_ms": "Minimum interval (ms) between draft message edits to avoid rate limits.\nOnly used when `stream_mode = \"partial\"`.",
    "enabled": "Whether this channel is active. The runtime only loads channels whose\n`enabled = true`. Default: `false` so an operator who pastes a partial\n`[channels.<type>.<alias>]` block doesn't accidentally bring a channel\nlive before the rest of its config is filled in.",
    "excluded_tools": "Tools excluded from this channel's tool spec. When set, these tools\nare not exposed to the model when responding via this channel.",
    "guild_ids": "Guild (server) IDs to restrict the bot to. Empty = listen across all\nguilds the bot is invited to. Migrated from the legacy `guild_id`\nsingular field.",
    "intents_mask": "Raw gateway intent mask override. When set, this exact value is sent\nin IDENTIFY instead of the derived mask: an operator escape hatch\nfor downstream deployments that consume gateway events through\ncustom builds or forks. The operator owns the consequences:\nprivileged bits still need their Developer Portal toggles, and\ndropping baseline bits silences message handling (a warning is\nlogged). Unset (default) = derive the mask from the channel's\nfeature config.",
    "interrupt_on_new_message": "When true, a newer Discord message from the same sender in the same channel\ncancels the in-flight request and starts a fresh response with preserved history.",
    "listen_to_bots": "When true, process messages from other bots (not just humans).\nThe bot still ignores its own messages to prevent feedback loops.",
    "mention_only": "When true, only respond to messages that @-mention the bot.\nOther messages in the guild are silently ignored.",
    "multi_message_delay_ms": "Delay (ms) between sending each message chunk in multi-message mode.\nOnly used when `stream_mode = \"multi_message\"`.",
    "proxy_url": "Per-channel proxy URL (http, https, socks5, socks5h).\nOverrides the global `[proxy]` setting for this channel only.",
    "reaction_notifications": "Which inbound reactions to record: `off` (default: reaction events\nare not even requested from the gateway), `own` (reactions to the\nbot's messages), or `all` (reactions to any message passing the\nchannel's filters). Recorded reactions are archived to `discord.db`\nwhen `archive` is enabled, and removed again when a user removes\ntheir reaction (bulk clears, remove-all / remove-emoji, are not\nyet swept). A set `intents_mask` overrides the derived mask: if it\nomits the reaction intents, nothing is recorded.",
    "reply_min_interval_secs": "Per-(channel, recipient) outbound pacing floor in seconds.\nRange: `0..=REPLY_MIN_INTERVAL_MAX_SECS` (0 disables).",
    "reply_queue_depth_max": "Per-(channel, recipient) outbound pacing queue depth.\nRange: `0..=REPLY_QUEUE_DEPTH_CEILING`. When `reply_min_interval_secs > 0`\nand this value is `0`, the pacing wrapper substitutes\n`DEFAULT_REPLY_QUEUE_DEPTH` (16). When the queue is full, the\nnewest send is dropped and a `WARN` is logged.",
    "slash_command_scope": "Scope for registered slash commands: `global` (default, application-wide,\n~1h propagation) or `guild` (registered to each `guild_ids` entry,\ninstant). Only meaningful when `slash_commands = true`; `guild` with an\nempty `guild_ids` warns and falls back to global. Switching scope reaps\nowned commands from the now-inactive scope; note that *removing* a guild\nfrom `guild_ids` (without switching scope) does not reap that guild's\ncommands - remove the bot from the guild, or switch scope, to clear them.",
    "slash_commands": "When true, register and serve Discord slash commands (e.g. `/ask`)\nover the Gateway WebSocket, in addition to message handling. Default\nfalse. (Prototype: currently registers a single `/ask <prompt>`.)",
    "stall_timeout_secs": "Stall-watchdog timeout in seconds. When non-zero, the bot will abort\nand retry if no progress is made within this duration. 0 = disabled.",
    "stream_mode": "Streaming mode for progressive response delivery.\n`off` (default): single message. `partial`: editable draft updates.\n`multi_message`: split response into separate messages at paragraph boundaries."
  },
  "DockerRuntimeConfig": {
    "allowed_workspace_roots": "Optional workspace root allowlist for fail-closed Docker mount validation: when `mount_workspace` is enabled, the workspace must exist and canonicalize even when this list is empty; every configured root must also exist and canonicalize; one invalid entry rejects the command before Docker starts; an empty list permits any canonical workspace.",
    "cpu_limit": "Optional CPU limit (`None` = no explicit limit).",
    "image": "Runtime image used to execute shell commands.",
    "memory_limit_mb": "Optional memory limit in MB (`None` = no explicit limit).",
    "mount_workspace": "Mount configured workspace into `/workspace`.\n\nWhen enabled, the workspace must exist and canonicalize before Docker\ncommand construction.",
    "network": "Docker network mode (`none`, `bridge`, etc.).",
    "read_only_rootfs": "Mount root filesystem as read-only."
  },
