  "GroqTranscriptionProviderConfig": {
    "api_key": "API key for the transcription provider.",
    "initial_prompt": "Whisper-style initial prompt to bias the model toward expected\nvocabulary (proper nouns, technical terms). Provider-specific support;\nsilently ignored where not applicable.",
    "language": "Optional language hint passed to the provider (ISO-639-1 like `\"en\"` /\n`\"ru\"`, or BCP-47 like `\"en-US\"` for Google). Most providers auto-detect\nwhen this is unset.",
    "model": "Whisper model name (default: `\"whisper-large-v3-turbo\"`)."
  },
  "HardwareConfig": {
    "baud_rate": "Baud rate negotiated on the serial link. 115200 matches the common Arduino / ESP32 bootloader default; bump to 230400+ when your firmware explicitly supports faster rates and you need the throughput.",
    "enabled": "Opt in to direct physical-hardware control — GPIO pins, USB-tethered microcontrollers (Arduino, ESP32, Nucleo), or SWD/JTAG debug probes. Leave off for software-only use; turning it on without the right transport configured does nothing.",
    "probe_target": "Target chip identifier for `transport = probe` (e.g. `STM32F401RE`, `nRF52840_xxAA`). Passed straight to probe-rs for flash/debug operations; must match a chip probe-rs recognizes.",
    "serial_port": "TTY path for the `serial` transport — e.g. `/dev/ttyACM0` on Linux, `/dev/tty.usbmodem1` on macOS, `COM3` on Windows. Ignored for other transports.",
    "transport": "How ZeroClaw reaches the hardware: `native` = Linux SBC with direct GPIO access (Raspberry Pi, Orange Pi); `serial` = USB-tethered microcontroller speaking over a TTY; `probe` = SWD/JTAG debug probe driving a target chip via probe-rs; `none` = disabled.",
    "workspace_datasheets": "Index pre-converted `.md` and `.txt` datasheets from the workspace into\na local RAG store, so the agent can look up pin assignments and\nelectrical specs inline when you ask hardware questions. PDFs are not\nparsed as text; download or convert them to `.md`/`.txt` first. Off by\ndefault — turn on once the workspace has relevant text datasheets."
  },
  "HeartbeatConfig": {
    "adaptive": "Enable adaptive intervals that back off on failures and speed up for\nhigh-priority tasks. Default: `false`.",
    "agent": "Configured agent alias the heartbeat worker runs as. Required\nwhen `enabled = true`; refers to a `[agents.<alias>]` entry.",
    "deadman_channel": "Channel for dead-man's switch alerts (e.g. `telegram`). Falls back to\nthe heartbeat delivery channel.",
    "deadman_timeout_minutes": "Dead-man's switch timeout in minutes. If the heartbeat has not ticked\nwithin this window, an alert is sent. `0` disables. Default: `0`.",
    "deadman_to": "Recipient for dead-man's switch alerts. Falls back to `to`.",
    "enabled": "Enable periodic heartbeat pings. Default: `false`. When enabled,\n`agent` must name a configured agent — there is no default agent\nfor heartbeat to fall through to.",
    "interval_minutes": "Interval in minutes between heartbeat pings. Minimum: `1`. Default: `30`.",
    "load_session_context": "Load the channel session history before each heartbeat task execution so\nthe LLM has conversational context. Default: `false`.\n\nWhen `true`, the session file for the configured `target`/`to` is passed\nto the agent as `session_state_file`, giving it access to the recent\nconversation history — just as if the user had sent a message.",
    "max_interval_minutes": "Maximum interval in minutes when adaptive mode backs off. Default: `120`.",
    "max_run_history": "Maximum number of heartbeat run history records to retain. Default: `100`.",
    "message": "Optional fallback task text when `HEARTBEAT.md` has no task entries.",
    "min_interval_minutes": "Minimum interval in minutes when adaptive mode is enabled. Default: `5`.",
    "target": "Optional delivery channel for heartbeat output (for example: `telegram`).\nWhen omitted, auto-selects the first configured channel.",
    "task_timeout_secs": "Maximum wall-clock seconds allowed for a single agent invocation\n(Phase 1 decision or Phase 2 task execution). `0` disables.\nDefault: `600` (10 minutes).",
    "to": "Optional delivery recipient/chat identifier (required when `target` is\nexplicitly set).",
    "two_phase": "Enable two-phase heartbeat: Phase 1 asks LLM whether to run, Phase 2\nexecutes only when the LLM decides there is work to do. Saves API cost\nduring quiet periods. Default: `true`."
  },
  "HooksConfig": {
    "enabled": "Enable lifecycle hook execution.\n\nHooks run in-process with the same privileges as the main runtime.\nKeep enabled hook handlers narrowly scoped and auditable."
  },
  "HttpRequestConfig": {
    "allow_private_hosts": "Allow requests to private/LAN hosts (RFC 1918, loopback, `.local`).\nDefault: false (deny private hosts for SSRF protection). Regardless of\nthis setting, all of `169.254.0.0/16`, Azure `168.63.129.16`, Alibaba\n`100.100.100.200`, AWS `fd00:ec2::/64`, GCP `fd20:ce::254`, and their\nrecognized IPv4-embedded forms remain blocked.",
    "allowed_domains": "Allowed domains for HTTP requests (exact or subdomain match)",
    "allowed_private_hosts": "Private/internal hosts explicitly allowed to relax the public-address check.\nExact and subdomain matches are supported; `*` permits private/local hosts\nexcept the unconditional metadata/platform exclusions: `169.254.0.0/16`,\n`168.63.129.16`, `100.100.100.200`, `fd00:ec2::/64`, `fd20:ce::254`, and\ntheir recognized IPv4-embedded forms.",
    "enabled": "Enable `http_request` tool for API interactions",
    "max_response_size": "Maximum response size in bytes (default: 1MB, 0 = unlimited)",
    "secrets": "Named authorization secrets for `auth_secret` requests.",
    "timeout_secs": "Request timeout in seconds (default: 30)"
  },
