  "NevisConfig": {
    "client_id": "OAuth2 client ID registered in Nevis.",
    "client_secret": "OAuth2 client secret. Encrypted via SecretStore when stored on disk.",
    "enabled": "Enable Nevis IAM integration. Defaults to false for backward compatibility.",
    "instance_url": "Base URL of the Nevis instance (e.g. `https://nevis.example.com`).",
    "jwks_url": "JWKS endpoint URL for local token validation.",
    "realm": "Nevis realm to authenticate against.",
    "require_mfa": "Require MFA verification for all Nevis-authenticated requests.",
    "role_mapping": "Nevis role to ZeroClaw permission mappings.",
    "session_timeout_secs": "Session timeout in seconds.",
    "token_validation": "Token validation strategy: `\"local\"` (JWKS) or `\"remote\"` (introspection)."
  },
  "NevisRoleMappingConfig": {
    "nevis_role": "Nevis role name (case-insensitive).",
    "workspace_access": "Workspace names this role can access. Use `\"all\"` for unrestricted.",
    "zeroclaw_permissions": "Tool names this role can access. Use `\"all\"` for unrestricted tool access."
  },
  "NextcloudTalkConfig": {
    "app_token": "Deprecated, unused. Nextcloud Talk sends do not authenticate via\nOCS bearer auth (see `webhook_secret`); this field is only accepted so\nexisting configs that set it don't fail to parse. Safe to remove\nfrom your config.",
    "base_url": "Nextcloud base URL (e.g. `\"https://cloud.example.com\"`).",
    "bot_name": "Display name of the bot in Nextcloud Talk (e.g. \"zeroclaw\").\nUsed to filter out the bot's own messages and prevent feedback loops.\nIf not set, defaults to an empty string (no self-message filtering by name).",
    "bot_token": "DEPRECATED alias for `webhook_secret`, kept for migration.\n\nNextcloud issues ONE secret per installed bot and uses it for both\ndirections, so this cannot hold a different outbound secret. When both\nare set to different non-empty values the channel logs the conflict and\nfails closed as unconfigured: inbound `401` and no outbound send.\nPrefer `webhook_secret`; this alias will be removed.\n\nUpgrade from a `bot_token`-only configuration: copy the installed bot\nsecret to `webhook_secret`, verify replies still send, then delete\n`bot_token`.",
    "draft_update_interval_ms": "Retained for configuration compatibility. Currently inert while draft\nupdates are disabled for this channel. Default: 1000 ms.",
    "enabled": "Whether this channel is active. The runtime only loads channels whose\n`enabled = true`. Default: `false` so an operator who pastes a partial\n`[channels.<type>.<alias>]` block doesn't accidentally bring a channel\nlive before the rest of its config is filled in.",
    "excluded_tools": "Tools excluded from this channel's tool spec. When set, these tools\nare not exposed to the model when responding via this channel.",
    "proxy_url": "Per-channel proxy URL (http, https, socks5, socks5h).\nOverrides the global `[proxy]` setting for this channel only.",
    "stream_mode": "Retained for configuration compatibility. Nextcloud Talk's bot API does\nnot provide message IDs or edit/delete operations, so draft updates are\ndisabled and responses are currently sent as one final message for every\nvalue.",
    "webhook_secret": "The bot secret Nextcloud installed for this bot. Canonical field.\n\nUsed for BOTH directions: verifying inbound webhook signatures and\nsigning outbound bot-API requests. When it is unset, inbound webhooks\nare rejected and no outbound request is sent (fail closed).\n\nCan also be set via `ZEROCLAW_NEXTCLOUD_TALK_WEBHOOK_SECRET`."
  },
  "NgrokTunnelConfig": {
    "auth_token": "ngrok auth token",
    "domain": "Optional custom domain"
  },
  "NodeRunOverlay": {
    "tool_calls": "Tool invocations captured while the step executed. Empty for\nunreached steps and runs recorded before capture landed."
  },
  "NodesConfig": {
    "auth_token": "Optional bearer token for node authentication.",
    "enabled": "Enable dynamic node discovery endpoint.",
    "max_nodes": "Maximum number of concurrent node connections.",
    "mdns": "LAN-local mDNS peer discovery."
  },
