  "PacingConfig": {
    "loop_detection_enabled": "Enable pattern-based loop detection (exact repeat, ping-pong,\nno-progress). Defaults to `true`.",
    "loop_detection_max_repeats": "Number of consecutive identical tool+args calls before the first\nescalation (Warning). Defaults to 3.",
    "loop_detection_min_elapsed_secs": "Minimum elapsed seconds before loop detection activates.\nTasks completing under this threshold get aggressive loop protection;\nlonger-running tasks receive a grace period before the detector starts\ncounting. `None` means loop detection is always active (existing behavior).",
    "loop_detection_window_size": "Sliding window size for the pattern-based loop detector.\nDefaults to 20.",
    "loop_ignore_tools": "Tool names excluded from identical-output / alternating-pattern loop\ndetection. Useful for browser workflows where `browser_screenshot`\nstructurally resembles a loop even when making progress.",
    "message_timeout_scale_max": "Override for the hardcoded timeout scaling cap (default: 4).\nThe channel message timeout budget is computed as:\n  `message_timeout_secs * min(max_tool_iterations, message_timeout_scale_max)`\nRaising this value lets long multi-step tasks with slow local models\nreceive a proportionally larger budget without inflating the base timeout.",
    "step_timeout_secs": "Per-step timeout in seconds: the maximum time allowed for a single\nLLM inference turn, independent of the total message budget.\n`None` means no per-step timeout (existing behavior)."
  },
  "PairingDashboardConfig": {
    "code_length": "Length of pairing codes (default: 8)",
    "code_ttl_secs": "Time-to-live for pending pairing codes in seconds (default: 3600)",
    "lockout_secs": "Lockout duration in seconds after max attempts (default: 300)",
    "max_failed_attempts": "Maximum failed pairing attempts before lockout (default: 5)",
    "max_pending_codes": "Maximum concurrent pending pairing codes (default: 3)"
  },
  "PatchOpResult": {
    "comment": "Comment that was applied alongside this op (if any). Echoed so\nclients can confirm the comment was actually written to disk\nwithout having to round-trip through `GET` and parse the TOML.",
    "value": "The resulting value at the target path after the op applied.\n`None` for secret paths (per the secrets-handling boundary), and for\n`remove` ops where the field was reset to its default."
  },
  "PatchResponse": {
    "warnings": "Non-fatal validation warnings against the saved configuration."
  },
  "PeerGroupConfig": {
    "admin_for_agent_scope": "When `true`, members of this peer group are authorized to issue\n`/model --agent <model>` on the agent this group is bound to.\nDefault `false` (deny-by-default). The runtime resolves this live\nfrom `Config::peer_groups` at command-dispatch time via\n`Config::channel_agent_scope_admins`; no cache, no per-channel\nduplicate sender list.",
    "agents": "Member agents by alias.",
    "channel": "Either a channel type (`\"telegram\"`) or a dotted channel alias\n(`\"telegram.work\"`). A bare type applies to every alias of that\ntype; a dotted form scopes the group to that single instance.",
    "external_peers": "Non-agent members by channel-native username.",
    "ignore": "Per-group blocklist; subtracts from the resolved peer set.",
    "output_modality": "Preferred output modality for all peers in this group.\nDefaults to `mirror` (input-driven). Set to `voice` to have the\nagent always reply and deliver proactive messages (cron, announces)\nas TTS voice notes on channels that support audio output."
  },
